import{_ as n,o as s,c as o,a6 as a,j as t}from"./chunks/framework.ERubKz-f.js";const i="/usa/sales-tax/images/nexus-sync-tooltip.webp",f=JSON.parse('{"title":"Update Your Sales Tax Nexus","description":"Add a nexus state in TaxJar, update the nexus in ERPNext at once, and fix the daily nexus update when the notification says that it failed.","frontmatter":{"title":"Update Your Sales Tax Nexus","description":"Add a nexus state in TaxJar, update the nexus in ERPNext at once, and fix the daily nexus update when the notification says that it failed.","type":"how-to"},"headers":[],"relativePath":"setting-up/updating-your-nexus.md","filePath":"setting-up/updating-your-nexus.md"}'),r={name:"setting-up/updating-your-nexus.md"};function u(d,e,c,l,h,p){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="updating-your-nexus" tabindex="-1">Updating your nexus <a class="header-anchor" href="#updating-your-nexus" aria-label="Permalink to &quot;Updating your nexus&quot;">​</a></h1><p>You collect sales tax only in the states where you have nexus, so a customer in any other state pays no sales tax. You manage your nexus states in TaxJar, and the app copies them to ERPNext every day.</p><h2 id="add-nexus-state" tabindex="-1">Add Nexus State <a class="header-anchor" href="#add-nexus-state" aria-label="Permalink to &quot;Add Nexus State&quot;">​</a></h2><ol><li>In TaxJar, go to <strong>Account → API Access → Nexus Address Configuration</strong>, and add the state. <a href="https://app.taxjar.com/account#api-access:~:text=Nexus%20Address%20Configuration" target="_blank" rel="noreferrer">Open the page in TaxJar</a></li><li>In ERPNext, <a href="#on-demand-nexus-sync">sync the nexus</a> to get the new state at once. If you do not, the daily update adds it.</li></ol><h2 id="on-demand-nexus-sync" tabindex="-1">On-Demand Nexus Sync <a class="header-anchor" href="#on-demand-nexus-sync" aria-label="Permalink to &quot;On-Demand Nexus Sync&quot;">​</a></h2>',5),t("p",null,[t("img",{src:i,alt:'The State Nexus section with the Synced caption, the refresh icon with the tooltip "Fetch nexus regions from TaxJar", and the nexus states of one company',width:"1772",height:"476",fetchpriority:"high"})],-1),a('<p>You need to be a TaxJar Manager. Refer to <a href="/usa/sales-tax/setting-up/roles-and-permissions">Roles &amp; Permissions</a>.</p><ol><li>In the TaxJar sidebar, click <strong>Nexus &amp; Product Category</strong>.</li><li>In <strong>State Nexus</strong>, click the refresh icon.</li><li>Wait for the message &quot;Nexus regions fetched and updated.&quot;</li><li>Check that the new state is in the company card. If a company has more than six states, click <strong>+{n} more</strong> to see all of them.</li></ol><h2 id="daily-update-failure" tabindex="-1">Daily Update Failure <a class="header-anchor" href="#daily-update-failure" aria-label="Permalink to &quot;Daily Update Failure&quot;">​</a></h2><p>If the daily update cannot get the nexus for a company, each TaxJar Manager and TaxJar User gets a notification under the bell icon. The notification names the cause, for example:</p><blockquote><p>TaxJar refreshed no nexus for {company}. No usable API credential.</p></blockquote><p>Until you fix the cause, the app uses the last nexus states that it got, so the tax calculation continues.</p><ol><li>Click the notification. <strong>Nexus &amp; Product Category</strong> opens.</li><li>Fix the cause. For a credential cause, check the token of the company in <a href="/usa/sales-tax/setting-up/guided-setup#connect">TaxJar Setup</a>.</li><li><a href="#on-demand-nexus-sync">Sync the nexus</a>. The <strong>Synced</strong> time changes only when the sync succeeds for all companies.</li></ol>',7)])])}const g=n(r,[["render",u]]);export{f as __pageData,g as default};
